import numpy as np

def show(M):
    for row in M:
        print("  [" + " ".join(f"{str(x):>5}" for x in row) + " ]")

def matmul(A, B):
    m, n, p = len(A), len(B), len(B[0])
    return [[sum(A[i][k] * B[k][j] for k in range(n)) for j in range(p)] for i in range(m)]

def paren(x):
    if x < 0:
        return f"({x})"
    return str(x)

def product(label, A, B):
    m, n, p = len(A), len(A[0]), len(B[0])
    print(f"{label}: ({m}×{n})({len(B)}×{p})")
    if n != len(B):
        print(f"  undefined: inner sizes {n} and {len(B)}")
        return
    C = matmul(A, B)
    for i in range(m):
        for j in range(p):
            terms = " + ".join(f"{paren(A[i][k])}({B[k][j]})" for k in range(n))
            print(f"  c{i + 1}{j + 1} = {terms} = {C[i][j]}")
    show(C)
    print(f"  numpy agrees: {np.array_equal(np.array(A) @ np.array(B), np.array(C))}")

product("Case 1 · the plain case", [[1, 2], [3, 4]], [[5, 6], [7, 8]])
product("Case 2 · 2×3 times 3×2", [[1, 0, 2], [-1, 3, 1]], [[3, 1], [2, 1], [1, 0]])
product("Case 3 · a row times a column", [[1, 2, 3]], [[4], [5], [6]])
product("Case 4 · a column times a row", [[1], [2], [3]], [[4, 5, 6]])
product("Case 5 · the sizes don't fit", [[1, 2, 3], [4, 5, 6]], [[1, 2, 3], [4, 5, 6]])
product("Case 6 · baskets and prices", [[2, 1, 3], [1, 4, 0]], [[150, 120], [300, 350], [80, 90]])

